def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    out = [row[:] for row in grid]

    for i in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
        for j in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[(r - r0) % (row_bounds[1] - 1)][
                        (c - c0) % (col_bounds[1] - 1)
                    ]
    return out
